"use client"
import * as React from "react"
import {cva,type VariantProps} from "class-variance-authority"
import {cn} from "@/lib/utils"
import {iconData,type IconNode} from "@/lib/sahajiv/icon-data"
import {useMorph} from "@/lib/sahajiv-motion/use-morph"
import {useFlowPress} from "@/lib/sahajiv-motion/flow-press"
function renderNode(node:IconNode,key:number):React.ReactNode{return React.createElement(node.tag,{...node.attrs,key},...node.children.map(renderNode))}
export type IconProps=React.ComponentProps<"svg"> & {name:string;size?:"default"|"sm"|"lg"}
export function Icon({name,size="default",className,...props}:IconProps){const nodes=iconData[name];if(!nodes)throw new Error(`Unknown SahaJiv icon: ${name}`);return <svg data-slot="icon" data-icon-name={name} viewBox="0 0 24 24" aria-hidden="true" className={cn("v-icon [width:var(--icon-md)] [height:var(--icon-md)] [stroke:currentColor] [stroke-width:var(--icon-stroke)] [stroke-linecap:round] [stroke-linejoin:round] [fill:none] [flex:none]",size!=="default"&&`-${size}`,className)} {...props}>{nodes.map(renderNode)}</svg>}
export const iconNames=Object.keys(iconData)
const DiskVariants=cva("v-disk [display:inline-grid] [place-items:center] [width:var(--disk-md)] [height:var(--disk-md)] [border-radius:50%] [background:var(--disk-bg,var(--v-beige))] [color:var(--v-text)] [flex:none]",{variants:{variant:{"default":"","pink":"-pink [--disk-bg:var(--v-pink)] [color:var(--v-on-accent)]","yellow":"-yellow [--disk-bg:var(--v-yellow)] [color:var(--v-on-accent)]","olive":"-olive [--disk-bg:var(--v-olive)] [color:var(--v-on-accent)]","blue":"-blue [--disk-bg:var(--v-blue)] [color:var(--v-on-accent)]","ink":"-ink [--disk-bg:var(--v-ink)] [color:var(--v-on-ink)]","cream":"-cream [--disk-bg:var(--v-canvas)]","beige":"-beige [--disk-bg:var(--v-beige)]"},size:{"default":"","sm":"-sm [width:var(--disk-sm)] [height:var(--disk-sm)]","lg":"-lg [width:var(--disk-lg)] [height:var(--disk-lg)]"}},defaultVariants:{variant:"default",size:"default"}})
export type DiskProps=React.ComponentProps<"span"> & VariantProps<typeof DiskVariants>
export function Disk({className,variant,size,ref,...props}:DiskProps){const morphRef=useMorph<HTMLSpanElement>("icons",ref);return <span ref={morphRef} data-slot="disk"  className={cn(DiskVariants({variant,size}),className)} {...props}/>}
const IconButtonVariants=cva("v-ibtn [display:inline-grid] [place-items:center] [width:var(--ctl-md)] [height:var(--ctl-md)] [border-radius:50%] [color:var(--v-text)] [background:transparent] [box-shadow:inset_0_0_0_1px_var(--v-border)] [transition:background_var(--t-micro),box-shadow_var(--t-micro)]",{variants:{variant:{"default":"","dashed":"-dashed [box-shadow:none] [border:1px_dashed_var(--v-text-2)] [border-color:var(--v-edge)]","ink":"-ink [background:var(--v-ink)] [color:var(--v-on-ink)] [box-shadow:none]","pink":"-pink [background:var(--v-pink)] [box-shadow:none] [color:var(--v-on-accent)]","beige":"-beige [background:var(--v-beige)] [box-shadow:inset_0_0_0_1px_var(--v-edge)] [color:var(--v-on-accent)]","cream":"-cream [background:var(--v-canvas)] [box-shadow:inset_0_0_0_1px_var(--v-edge)]"},size:{"default":"","sm":"-sm [width:var(--ctl-sm)] [height:var(--ctl-sm)]","lg":"-lg [width:var(--ctl-lg)] [height:var(--ctl-lg)]","xl":"-xl [width:var(--dock-action)] [height:var(--dock-action)]"}},defaultVariants:{variant:"default",size:"default"}})
export type IconButtonProps=React.ComponentProps<"button"> & VariantProps<typeof IconButtonVariants>
export function IconButton({className,variant,size,ref,...props}:IconButtonProps){const morphRef=useMorph<HTMLButtonElement>("icons",ref);const ownedRef=useFlowPress(morphRef);return <button ref={ownedRef} data-slot="icon-button" type="button" className={cn(IconButtonVariants({variant,size}),className)} {...props}/>}

@layer sahajiv-states {
/* Icon primitive state and contextual geometry. */
.v-icon:where([data-slot]).-sm{width:var(--icon-sm);height:var(--icon-sm)}
.v-icon:where([data-slot]).-lg{width:var(--icon-lg);height:var(--icon-lg)}
.v-disk:where([data-slot]).-sm{width:var(--disk-sm);height:var(--disk-sm)}
.v-disk:where([data-slot]).-lg{width:var(--disk-lg);height:var(--disk-lg)}
.v-disk:where([data-slot]).-pink{--disk-bg:var(--v-pink);color:var(--v-on-accent)}
.v-disk:where([data-slot]).-yellow{--disk-bg:var(--v-yellow);color:var(--v-on-accent)}
.v-disk:where([data-slot]).-olive{--disk-bg:var(--v-olive);color:var(--v-on-accent)}
.v-disk:where([data-slot]).-blue{--disk-bg:var(--v-blue);color:var(--v-on-accent)}
.v-disk:where([data-slot]).-ink{--disk-bg:var(--v-ink);color:var(--v-on-ink)}
.v-disk:where([data-slot]).-cream{--disk-bg:var(--v-canvas)}
.v-disk:where([data-slot]).-beige{--disk-bg:var(--v-beige)}
.v-ibtn:where([data-slot]).-dashed{box-shadow:none;border:1px dashed var(--v-text-2);border-color:var(--v-edge)}
.v-ibtn:where([data-slot]).-ink{background:var(--v-ink);color:var(--v-on-ink);box-shadow:none}
.v-ibtn:where([data-slot]).-pink{background:var(--v-pink);box-shadow:none;color:var(--v-on-accent)}
.v-ibtn:where([data-slot]).-beige{background:var(--v-beige);box-shadow:inset 0 0 0 1px var(--v-edge);color:var(--v-on-accent)}
.v-ibtn:where([data-slot]).-cream{background:var(--v-canvas);box-shadow:inset 0 0 0 1px var(--v-edge)}
.v-ibtn:where([data-slot]).-sm{width:var(--ctl-sm);height:var(--ctl-sm)}
.v-ibtn:where([data-slot]).-lg{width:var(--ctl-lg);height:var(--ctl-lg)}
.v-ibtn:where([data-slot]).-xl{width:var(--dock-action);height:var(--dock-action)}
.v-disk:where([data-slot]).-sm .v-icon{width:16px;height:16px}
.v-disk:where([data-slot]).-lg .v-icon{width:24px;height:24px}
.v-ibtn:where([data-slot])[data-morph][data-hover]{--mfill:var(--v-beige)}
.v-ibtn:where([data-slot]).-ink[data-morph]{--mfill:var(--v-ink)}
.v-ibtn:where([data-slot]).-ink[data-morph][data-hover]{--mfill:var(--v-ink-soft)}
.v-ibtn:where([data-slot]).-pink[data-morph]{--mfill:var(--v-pink)}
.v-ibtn:where([data-slot]).-pink[data-morph][data-hover]{--mfill:var(--v-pink-deep)}
.v-ibtn:where([data-slot]).-beige[data-morph]{--mfill:var(--v-beige)}
.v-ibtn:where([data-slot]).-cream[data-morph]{--mfill:var(--v-canvas)}
.v-disk:where([data-slot])[data-morph]{--mfill:var(--disk-bg,var(--v-beige))}
[data-colourful="1"] .v-disk:where([data-slot]):not([class*=" -"]){background:var(--v-blue-soft)}
.v-ibtn:where([data-slot]):hover{background:var(--v-beige)}
.v-ibtn:where([data-slot]).-ink:hover{background:var(--v-ink-soft)}
.v-ibtn:where([data-slot]).-pink:hover{background:var(--v-pink-deep)}
.v-ibtn:where([data-slot]).-sm .v-icon{width:16px;height:16px}
.v-ibtn:where([data-slot]).-xl .v-icon{width:24px;height:24px}
.v-ibtn:where([data-slot]):disabled{opacity:.4;cursor:not-allowed}
.v-ibtn:where([data-slot]):not(.-ink):not(.-pink):not(.-beige):not(.-cream):not(.-dashed){box-shadow:inset 0 0 0 1px var(--v-edge)}
:root[data-mode="dark"] .v-ibtn:where([data-slot]){color:var(--v-text)}
.v-ibtn:where([data-slot]):disabled{background:var(--v-disabled-face);color:var(--v-disabled-ink);box-shadow:inset 0 0 0 1px var(--v-disabled-edge);opacity:1}

}
